#!/usr/bin/env bash
# gen_main.sh -- regenerate main.tex from the photos in photos/ (deterministic).
# The EXIF orientations of all pool photos are read first; the layout is
# generated by gen_main.awk with a fixed seed.
set -euo pipefail
cd "$(dirname "$0")"

nix-shell -p exiftool --run 'cd photos && exiftool -Orientation -ImageWidth -ImageHeight *.jpg *.jpeg 2>/dev/null' > /tmp/opencode/photos_raw.txt
awk -f gen_parse.awk /tmp/opencode/photos_raw.txt | LC_ALL=C sort > /tmp/opencode/photos_sorted.tsv
awk -f gen_main.awk /tmp/opencode/photos_sorted.tsv > main.tex
echo "gen_main: main.tex written ($(grep -c '^%% ---------- page' main.tex) pages)"
